package com.aoo.bcg.wordcard;import java.util.*;import java.util.stream.*;/**临川字牌（长汀510K）牌型权威，移植 LCZP optype 十六类实现。*/final class LczpRules{enum Type{PASS,SINGLE,PAIR,QUAN_HE,DA_MIAN,XIAO_MIAN,KAN,KAN_ONE,KAN_TWO,DA_XIAO_KAN,LONG,LONG_ONE,LONG_TWO,LONG_THREE,DA_XIAO_LONG,STRAIGHT}record Play(Type type,List<Integer>cards,int value,int chainLength){Play{cards=List.copyOf(cards);}}private LczpRules(){}static List<Integer>deck(){List<Integer>x=new ArrayList<>(44);for(int type=10;type<=20;type++)for(int copy=1;copy<=4;copy++)x.add(type*100+copy);return List.copyOf(x);}static int rank(int c){return c/100;}static int color(int c){return c%100;}static int point510k(int c){return Set.of(15,20).contains(rank(c))?10:0;}static Play classify(Type d,Collection<Integer>input){if(input==null||input.isEmpty())throw new IllegalArgumentException("LCZP cards required");List<Integer>c=List.copyOf(input);Map<Integer,Long>m=c.stream().collect(Collectors.groupingBy(LczpRules::rank,TreeMap::new,Collectors.counting()));int min=m.keySet().iterator().next(),max=m.keySet().stream().mapToInt(x->x).max().orElse(min);boolean same=m.size()==1,continuous=max-min+1==m.size();boolean ok=switch(d){case SINGLE->c.size()==1;case PAIR->c.size()==2&&same;case QUAN_HE->c.size()>=4&&m.values().stream().allMatch(n->n==2);case DA_MIAN,XIAO_MIAN->c.size()>=3&&continuous;case KAN->c.size()==3&&same;case KAN_ONE->c.size()==4&&m.containsValue(3L);case KAN_TWO->c.size()==5&&m.containsValue(3L);case DA_XIAO_KAN->c.size()==6&&m.values().stream().allMatch(n->n==3);case LONG->c.size()==4&&same;case LONG_ONE->c.size()==5&&m.containsValue(4L);case LONG_TWO->c.size()==6&&m.containsValue(4L);case LONG_THREE->c.size()==7&&m.containsValue(4L);case DA_XIAO_LONG->c.size()==8&&m.values().stream().allMatch(n->n==4);case STRAIGHT->c.size()>=3&&m.values().stream().allMatch(n->n==1)&&continuous;case PASS->false;};if(!ok)throw new IllegalArgumentException("invalid LCZP "+d);return new Play(d,c,min,m.size());}static boolean beats(Play n,Play p){if(p==null)return true;if(n.type()==p.type())return n.cards().size()==p.cards().size()&&n.value()>p.value();return power(n.type())>power(p.type());}private static int power(Type t){return switch(t){case DA_XIAO_LONG->9;case LONG,LONG_ONE,LONG_TWO,LONG_THREE->8;case DA_XIAO_KAN->7;case KAN,KAN_ONE,KAN_TWO->6;case QUAN_HE->5;default->1;};}static int prize(Play p,boolean redCuo,boolean blackCuo,boolean fanCuo){int base=p.type().name().contains("LONG")?4:p.type().name().contains("KAN")?2:0;if(redCuo&&p.cards().stream().allMatch(c->color(c)%2==1)||blackCuo&&p.cards().stream().allMatch(c->color(c)%2==0))base+=5;return fanCuo?base*2:base;}}
